import type {
    EntitySchema,
    FieldSchema,
    RepeaterSubfield,
} from '@flexacms/client';

/**
 * Turn entity schemas into TypeScript declarations: one `<Entity>Values`
 * interface per entity and a `FlexaSchema` map for `createClient<FlexaSchema>()`.
 */
export function generateTypes(schemas: EntitySchema[]): string {
    const lines = [
        '// Generated by @flexacms/cli. Do not edit by hand: run `npx @flexacms/cli generate` again instead.',
        "import type { Localized } from '@flexacms/client';",
        '',
    ];

    const names = new Map<string, string>();

    for (const schema of schemas) {
        names.set(
            schema.slug,
            uniqueName(`${pascalCase(schema.slug)}Values`, names),
        );
    }

    for (const schema of schemas) {
        lines.push(
            `/** ${schema.name}${schema.description ? ` — ${schema.description}` : ''} */`,
        );
        lines.push(`export interface ${names.get(schema.slug)} {`);

        for (const field of schema.fields.filter(
            (item) => item.is_active !== false,
        )) {
            const type = fieldType(field);
            const doc = [field.label, field.description]
                .filter(Boolean)
                .join(' — ');

            lines.push(`    /** ${escapeComment(doc)} */`);
            lines.push(
                `    ${propertyName(field.key)}: ${field.is_required ? type : `${wrap(type)} | null`};`,
            );
        }

        lines.push('}', '');
    }

    lines.push('export interface FlexaSchema {');

    for (const schema of schemas) {
        lines.push(
            `    ${propertyName(schema.slug)}: ${names.get(schema.slug)};`,
        );
    }

    lines.push('}', '');

    return lines.join('\n');
}

function fieldType(field: FieldSchema): string {
    const base = baseType(field);

    return field.translatable ? `Localized<${base}>` : base;
}

function baseType(
    field: Pick<
        FieldSchema,
        'type' | 'options' | 'multiple' | 'address_parts' | 'repeater_subfields'
    >,
): string {
    switch (field.type) {
        case 'number':
            return 'number';
        case 'boolean':
            return 'boolean';
        case 'select':
            return optionsUnion(field.options);
        case 'multiselect':
            return `${wrap(optionsUnion(field.options))}[]`;
        case 'tags':
            return 'string[]';
        case 'image':
        case 'file':
            return field.multiple ? 'string[]' : 'string';
        case 'relationship':
            return field.multiple ? 'number[]' : 'number';
        case 'json':
            return 'unknown';
        case 'address':
            return `{ ${(
                field.address_parts ?? [
                    'street',
                    'city',
                    'state',
                    'postal_code',
                    'country',
                ]
            )
                .map((part) => `${propertyName(part)}?: string | null`)
                .join('; ')} }`;
        case 'repeater':
            return `Array<${repeaterItem(field.repeater_subfields)}>`;
        default:
            return 'string';
    }
}

function repeaterItem(subfields: RepeaterSubfield[] | null): string {
    if (!subfields || subfields.length === 0) {
        return 'Record<string, unknown>';
    }

    const properties = subfields.map((subfield) => {
        const type = baseType({
            type: subfield.type,
            options: isOptionMap(subfield.options) ? subfield.options : null,
            multiple: Boolean(
                (subfield.settings as Record<string, unknown> | undefined)
                    ?.multiple ?? subfield.multiple,
            ),
            address_parts: undefined,
            repeater_subfields: null,
        });

        return subfield.is_required === true
            ? `${propertyName(subfield.key)}: ${type}`
            : `${propertyName(subfield.key)}?: ${wrap(type)} | null`;
    });

    return `{ ${properties.join('; ')} }`;
}

function optionsUnion(
    options: Record<string, string> | null | undefined,
): string {
    const keys = isOptionMap(options) ? Object.keys(options) : [];

    return keys.length > 0
        ? keys.map((key) => JSON.stringify(key)).join(' | ')
        : 'string';
}

function isOptionMap(value: unknown): value is Record<string, string> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** Parenthesize unions so `| null` and `[]` apply to the whole type. */
function wrap(type: string): string {
    let depth = 0;

    for (let index = 0; index < type.length; index++) {
        const character = type[index];

        if (
            character === '(' ||
            character === '[' ||
            character === '{' ||
            character === '<'
        ) {
            depth++;
        } else if (
            character === ')' ||
            character === ']' ||
            character === '}' ||
            character === '>'
        ) {
            depth--;
        } else if (depth === 0 && type.startsWith(' | ', index)) {
            return `(${type})`;
        }
    }

    return type;
}

function pascalCase(value: string): string {
    const name = value
        .split(/[^A-Za-z0-9]+/)
        .filter(Boolean)
        .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
        .join('');

    return /^[0-9]/.test(name) || name === '' ? `Entity${name}` : name;
}

function uniqueName(name: string, taken: Map<string, string>): string {
    const used = new Set(taken.values());
    let candidate = name;
    let suffix = 2;

    while (used.has(candidate)) {
        candidate = `${name}${suffix++}`;
    }

    return candidate;
}

function propertyName(key: string): string {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key);
}

function escapeComment(text: string): string {
    return text.replace(/\*\//g, '*\\/').replace(/\s+/g, ' ').trim();
}
